import struct
from binascii import hexlify

def encode_length(length):
    """Encode DER length"""
    if length < 128:
        return bytes([length])
    elif length < 256:
        return b'\x81' + bytes([length])
    else:
        return b'\x82' + struct.pack('>H', length)

def encode_sequence(data):
    """Wrap data in SEQUENCE tag"""
    return b'\x30' + encode_length(len(data)) + data

def encode_octet_string(data):
    """Wrap data in OCTET STRING tag"""
    return b'\x04' + encode_length(len(data)) + data

def encode_context_specific(tag, data):
    """Wrap data in context-specific tag"""
    return bytes([0xa0 + tag]) + encode_length(len(data)) + data

def encode_oid(oid_string):
    """Encode OID - simplified for known OIDs"""
    oids = {
        '1.2.840.113549.1.7.1': b'\x06\x09\x2a\x86\x48\x86\xf7\x0d\x01\x07\x01',  # data
        '1.2.840.113549.1.12.10.1.4': b'\x06\x0b\x2a\x86\x48\x86\xf7\x0d\x01\x0c\x0a\x01\x04',  # crlBag
        '1.2.840.113549.1.9.23': b'\x06\x09\x2a\x86\x48\x86\xf7\x0d\x01\x09\x17',  # x509Crl
    }
    return oids.get(oid_string, b'')

def encode_integer(value):
    """Encode INTEGER"""
    if value < 128:
        return b'\x02\x01' + bytes([value])
    else:
        # For larger values, would need more logic
        return b'\x02\x01' + bytes([value & 0xFF])

# Create invalid CRL data that will fail import but is somewhat structured
# A CRL should have: SEQUENCE { tbsCertList, signatureAlgorithm, signatureValue }
# We'll make it invalid by having incorrect structure
invalid_crl = encode_sequence(
    encode_integer(1) +  # version (wrong type/structure)
    b'\x05\x00'  # NULL (incomplete, missing required fields)
)

# Create CRL bag value
crl_value = encode_context_specific(0, encode_octet_string(invalid_crl))
crl_bag_value = encode_sequence(encode_oid('1.2.840.113549.1.9.23') + crl_value)

# Create SafeBag for CRL
safe_bag = encode_sequence(
    encode_oid('1.2.840.113549.1.12.10.1.4') +  # crlBag OID
    encode_context_specific(0, crl_bag_value)
)

# Wrap in SafeBag sequence
safe_bags = encode_sequence(safe_bag)

# Wrap in OCTET STRING
safe_contents = encode_octet_string(safe_bags)

# Wrap in ContentInfo with data OID
content_info = encode_sequence(
    encode_oid('1.2.840.113549.1.7.1') +
